"""Reviewed NL -> SQL pairs for the Pecos Ridge OpenInvoice supply-chain demo.

`demo rq-check pecos_openinvoice --snowflake` executes every pair against DuckDB and our Snowflake;
Wells, AFEs and vendors are joined through OpenInvoice's own synced copies (OI_REF_*) because our
database and the partner's 26 live on different Snowflake accounts and one query runs on one connection.
NL text must not contain commas; SQL is portable (ANSI CASE, DATE literals, EXTRACT, NULLIF).
eval_only pairs stay in rq-check and the eval set but out of the certified query library.
"""
from demo_creator.reviewed_queries import Registry

rq = Registry()
add = rq.add


def add_eval_only(nl, sql):
    rq.add(nl, sql, tags=("eval_only",))


def add_cross(nl, sql, eval_only=False):
    rq.add(nl, sql, tags=("cross_db", "eval_only") if eval_only else ("cross_db",))


HERO = "Corrosion inhibitor, water-soluble, filming amine"
CASING = "Production casing 5-1/2 in 20 lb/ft P-110 BTC"
SAND100 = "Regional sand, 100 mesh"
MDM = "PECOS_RIDGE_CORP_MDM.MASTER"
SCM = "PECOS_RIDGE_PROCUREMENT_SCM.SCM"
QF = "PECOS_RIDGE_REV_ACCOUNTING.QUORUM_FIN"
WV = "PECOS_RIDGE_DRILLING_WELLVIEW.WV"
PLAN = "PECOS_RIDGE_DEV_PLANNING.PLAN"
OI = "PECOS_RIDGE_SCM_OPENINVOICE.OPENINVOICE"

# ---------------------------------------------------------------- lookups and orientation
add("List every supplier onboarded to OpenInvoice with its category and basin and onboarding date and flags sorted with price-book suppliers first then by name.",
    "SELECT OI_SUPPLIER_ID, SUPPLIER_NAME, LIFNR, OI_SUPPLIER_CATEGORY, PRIMARY_BASIN, ONBOARDED_DATE, EINVOICE_ENABLED, PRICEBOOK_LOADED FROM OI_SUPPLIER ORDER BY PRICEBOOK_LOADED DESC, SUPPLIER_NAME")
add("List each taxonomy family and class with the number of generic products and the category manager.",
    "SELECT LEVEL1_FAMILY, LEVEL2_CLASS, COUNT(*) AS GENERIC_PRODUCTS, MIN(CATEGORY_MANAGER) AS CATEGORY_MANAGER FROM SCM_PRODUCT_TAXONOMY GROUP BY LEVEL1_FAMILY, LEVEL2_CLASS ORDER BY LEVEL1_FAMILY, LEVEL2_CLASS")
add("How much OpenInvoice line spend do we have by year and by supplier category?",
    "SELECT INVOICE_YEAR, OI_SUPPLIER_CATEGORY, COUNT(DISTINCT OI_INVOICE_ID) AS INVOICES, COUNT(*) AS LINES, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD FROM V_INVOICE_LINE_CLASSIFIED GROUP BY INVOICE_YEAR, OI_SUPPLIER_CATEGORY ORDER BY INVOICE_YEAR, SPEND_USD DESC")
add("What share of invoices carries a stamped ERP invoice id by year?",
    "SELECT EXTRACT(YEAR FROM INVOICE_DATE) AS INVOICE_YEAR, COUNT(*) AS INVOICES, SUM(CASE WHEN ERP_INVOICE_ID IS NOT NULL THEN 1 ELSE 0 END) AS STAMPED, ROUND(100.0 * SUM(CASE WHEN ERP_INVOICE_ID IS NOT NULL THEN 1 ELSE 0 END) / COUNT(*), 1) AS STAMPED_PCT FROM OI_INVOICE GROUP BY EXTRACT(YEAR FROM INVOICE_DATE) ORDER BY INVOICE_YEAR")
add_eval_only("Count 2026 field tickets and sum their totals by approver name sorted by total.",
              "SELECT APPROVED_BY, COUNT(*) AS TICKETS, ROUND(SUM(TICKET_TOTAL_USD), 0) AS TICKET_TOTAL_USD FROM OI_FIELD_TICKET WHERE TICKET_DATE >= DATE '2026-01-01' GROUP BY APPROVED_BY ORDER BY TICKET_TOTAL_USD DESC")

# ---------------------------------------------------------------- spend by generic product (the new context)
add("What did we spend in 2025 by generic product and what is the standard unit price we paid?",
    "SELECT LEVEL1_FAMILY, GENERIC_PRODUCT_NAME, STANDARD_UOM, ROUND(SUM(STD_QUANTITY), 0) AS STD_QUANTITY, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD, ROUND(SUM(LINE_AMOUNT_USD) / NULLIF(SUM(STD_QUANTITY), 0), 2) AS STD_UNIT_PRICE_USD, COUNT(DISTINCT LIFNR) AS SUPPLIERS FROM V_INVOICE_LINE_CLASSIFIED WHERE INVOICE_YEAR = 2025 AND IS_CLASSIFIED = 1 AND LEVEL1_FAMILY <> 'Fees & surcharges' GROUP BY LEVEL1_FAMILY, GENERIC_PRODUCT_NAME, STANDARD_UOM ORDER BY SPEND_USD DESC")
add("Show chemical spend by generic product and primary use for 2025 and 2026.",
    "SELECT GENERIC_PRODUCT_NAME, PRIMARY_USE, USE_PHASE, INVOICE_YEAR, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD, ROUND(SUM(STD_QUANTITY), 0) AS GALLONS FROM V_INVOICE_LINE_CLASSIFIED WHERE LEVEL1_FAMILY = 'Production & completion chemicals' AND INVOICE_YEAR >= 2025 GROUP BY GENERIC_PRODUCT_NAME, PRIMARY_USE, USE_PHASE, INVOICE_YEAR ORDER BY GENERIC_PRODUCT_NAME, INVOICE_YEAR")
add("For 2025 show spend by OpenInvoice cost code and its description crossed with generic product family with the number of distinct generic products in each cell.",
    "SELECT OI_COST_CODE, OI_COST_CODE_DESC, LEVEL1_FAMILY, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD, COUNT(DISTINCT GENERIC_PRODUCT_NAME) AS GENERIC_PRODUCTS FROM V_INVOICE_LINE_CLASSIFIED WHERE INVOICE_YEAR = 2025 GROUP BY OI_COST_CODE, OI_COST_CODE_DESC, LEVEL1_FAMILY ORDER BY OI_COST_CODE, SPEND_USD DESC")
add("For regional sand 100 mesh combined over 2025 to date list each supplier item description with its invoiced UOM and total tons and the price per ton.",
    f"SELECT SUPPLIER_NAME, SUPPLIER_ITEM_CODE, SUPPLIER_ITEM_DESCRIPTION, INVOICED_UOM, ROUND(SUM(STD_QUANTITY), 0) AS TONS, ROUND(SUM(LINE_AMOUNT_USD) / NULLIF(SUM(STD_QUANTITY), 0), 2) AS USD_PER_TON FROM V_INVOICE_LINE_CLASSIFIED WHERE GENERIC_PRODUCT_NAME = '{SAND100}' AND INVOICE_YEAR >= 2025 GROUP BY SUPPLIER_NAME, SUPPLIER_ITEM_CODE, SUPPLIER_ITEM_DESCRIPTION, INVOICED_UOM ORDER BY USD_PER_TON")
add_eval_only("Show the monthly rows of V_GENERIC_PRODUCT_PRICE_MONTHLY for H2S scavenger triazine by supplier since January 2024 with gallons and the average standard unit price per row.",
              "SELECT INVOICE_MONTH, SUPPLIER_NAME, ROUND(AVG_STD_UNIT_PRICE_USD, 2) AS USD_PER_GAL, ROUND(STD_QUANTITY, 0) AS GALLONS FROM V_GENERIC_PRODUCT_PRICE_MONTHLY WHERE GENERIC_PRODUCT_NAME = 'H2S scavenger, triazine' AND INVOICE_MONTH >= DATE '2024-01-01' ORDER BY INVOICE_MONTH, SUPPLIER_NAME")

# ---------------------------------------------------------------- CP1: hidden price dispersion
add("What did we pay per gallon for water-soluble corrosion inhibitor by supplier in 2025 and how much would we have saved at the best observed price?",
    f"SELECT SUPPLIER_NAME, ROUND(STD_QUANTITY, 0) AS GALLONS, ROUND(SPEND_USD, 0) AS SPEND_USD, ROUND(AVG_STD_UNIT_PRICE_USD, 2) AS USD_PER_GAL, ROUND(BEST_STD_UNIT_PRICE_USD, 2) AS BEST_USD_PER_GAL, ROUND(VOLUME_SHARE * 100, 1) AS VOLUME_SHARE_PCT, ROUND(SAVINGS_AT_BEST_PRICE_USD, 0) AS SAVINGS_AT_BEST_PRICE_USD, ROUND(PRICE_DISPERSION_PCT, 1) AS PRICE_DISPERSION_PCT FROM V_SUPPLIER_ALTERNATIVES WHERE GENERIC_PRODUCT_NAME = '{HERO}' AND INVOICE_YEAR = 2025 ORDER BY AVG_STD_UNIT_PRICE_USD")
add("Break down the 2025 corrosion inhibitor price per gallon by supplier and pack size.",
    f"SELECT SUPPLIER_NAME, SUPPLIER_ITEM_DESCRIPTION, INVOICED_UOM, COUNT(*) AS LINES, ROUND(SUM(STD_QUANTITY), 0) AS GALLONS, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD, ROUND(SUM(LINE_AMOUNT_USD) / NULLIF(SUM(STD_QUANTITY), 0), 2) AS USD_PER_GAL FROM V_INVOICE_LINE_CLASSIFIED WHERE GENERIC_PRODUCT_NAME = '{HERO}' AND INVOICE_YEAR = 2025 GROUP BY SUPPLIER_NAME, SUPPLIER_ITEM_DESCRIPTION, INVOICED_UOM ORDER BY USD_PER_GAL DESC")
add("For every generic product bought from more than one supplier in 2025 show supplier count and price dispersion percent and best and highest price and total spend and savings at the best price sorted by savings; return all of them.",
    "SELECT GENERIC_PRODUCT_NAME, STANDARD_UOM, MAX(SUPPLIER_COUNT) AS SUPPLIERS, ROUND(MAX(PRICE_DISPERSION_PCT), 1) AS PRICE_DISPERSION_PCT, ROUND(MIN(BEST_STD_UNIT_PRICE_USD), 2) AS BEST_PRICE, ROUND(MAX(HIGHEST_STD_UNIT_PRICE_USD), 2) AS HIGHEST_PRICE, ROUND(SUM(SPEND_USD), 0) AS SPEND_USD, ROUND(SUM(SAVINGS_AT_BEST_PRICE_USD), 0) AS SAVINGS_AT_BEST_PRICE_USD FROM V_SUPPLIER_ALTERNATIVES WHERE INVOICE_YEAR = 2025 AND SUPPLIER_COUNT > 1 GROUP BY GENERIC_PRODUCT_NAME, STANDARD_UOM ORDER BY SAVINGS_AT_BEST_PRICE_USD DESC")
add("For Basin Chemical water-soluble corrosion inhibitor in 2025 split gallons and spend and price per gallon into two groups: small packs meaning pails and drums versus totes and bulk.",
    f"SELECT CASE WHEN INVOICED_UOM IN ('PAIL', 'DRUM') THEN 'Small pack' ELSE 'Tote or bulk' END AS PACK_GROUP, ROUND(SUM(STD_QUANTITY), 0) AS GALLONS, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD, ROUND(SUM(LINE_AMOUNT_USD) / NULLIF(SUM(STD_QUANTITY), 0), 2) AS USD_PER_GAL FROM V_INVOICE_LINE_CLASSIFIED WHERE GENERIC_PRODUCT_NAME = '{HERO}' AND INVOICE_YEAR = 2025 AND LIFNR = '0000100040' GROUP BY CASE WHEN INVOICED_UOM IN ('PAIL', 'DRUM') THEN 'Small pack' ELSE 'Tote or bulk' END ORDER BY PACK_GROUP")
add_eval_only("For the two chemical suppliers in 2025 show only the accounting view from the invoice lines: supplier name and supplier category and cost code with invoice count and spend and the number of distinct item descriptions.",
              "SELECT SUPPLIER_NAME, OI_SUPPLIER_CATEGORY, OI_COST_CODE, COUNT(DISTINCT OI_INVOICE_ID) AS INVOICES, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD, COUNT(DISTINCT SUPPLIER_ITEM_DESCRIPTION) AS DISTINCT_ITEM_DESCRIPTIONS FROM V_INVOICE_LINE_CLASSIFIED WHERE LIFNR IN ('0000100039', '0000100040') AND INVOICE_YEAR = 2025 GROUP BY SUPPLIER_NAME, OI_SUPPLIER_CATEGORY, OI_COST_CODE ORDER BY SUPPLIER_NAME")
add("Which basin pays the most per gallon for water-soluble corrosion inhibitor in 2026 and from which supplier?",
    f"SELECT BASIN, SUPPLIER_NAME, ROUND(SUM(STD_QUANTITY), 0) AS GALLONS, ROUND(SUM(LINE_AMOUNT_USD) / NULLIF(SUM(STD_QUANTITY), 0), 2) AS USD_PER_GAL FROM V_INVOICE_LINE_CLASSIFIED WHERE GENERIC_PRODUCT_NAME = '{HERO}' AND INVOICE_YEAR = 2026 AND BASIN IS NOT NULL GROUP BY BASIN, SUPPLIER_NAME ORDER BY USD_PER_GAL DESC")

# ---------------------------------------------------------------- CP2: price book variance and disputes
add("By supplier for 2026 count the price-book lines invoiced above contract with total variance and average variance percent and how many of those lines are disputed.",
    "SELECT SUPPLIER_NAME, COUNT(*) AS LINES_OVER_CONTRACT, ROUND(SUM(PRICE_VARIANCE_USD), 0) AS VARIANCE_USD, ROUND(AVG(PRICE_VARIANCE_PCT), 1) AS AVG_VARIANCE_PCT, SUM(CASE WHEN LINE_STATUS = 'Disputed' THEN 1 ELSE 0 END) AS DISPUTED_LINES FROM V_PRICEBOOK_VARIANCE WHERE INVOICE_YEAR = 2026 AND IS_OVER_CONTRACT = 1 GROUP BY SUPPLIER_NAME ORDER BY VARIANCE_USD DESC")
add("By month in 2026 for Redline Sand item RL100 show line count and the simple average invoiced price per ton and the average contract rate and total variance and the disputed line amount.",
    "SELECT INVOICE_MONTH, COUNT(*) AS LINES, ROUND(AVG(UNIT_PRICE_USD), 2) AS AVG_INVOICED_USD_PER_TON, ROUND(AVG(PRICEBOOK_RATE_USD), 2) AS CONTRACT_USD_PER_TON, ROUND(SUM(PRICE_VARIANCE_USD), 0) AS VARIANCE_USD, ROUND(SUM(CASE WHEN LINE_STATUS = 'Disputed' THEN LINE_AMOUNT_USD ELSE 0 END), 0) AS DISPUTED_AMOUNT_USD FROM V_PRICEBOOK_VARIANCE WHERE LIFNR = '0000100043' AND SUPPLIER_ITEM_CODE = 'RL100' AND INVOICE_YEAR = 2026 GROUP BY INVOICE_MONTH ORDER BY INVOICE_MONTH")
add("List disputed invoices with the OpenInvoice id and supplier invoice number and supplier name and invoice date and total and the dispute reason and the ERP invoice id sorted newest first.",
    "SELECT i.OI_INVOICE_ID, i.SUPPLIER_INVOICE_NUMBER, s.SUPPLIER_NAME, i.INVOICE_DATE, i.INVOICE_TOTAL_USD, i.DISPUTE_REASON, i.ERP_INVOICE_ID FROM OI_INVOICE i JOIN OI_SUPPLIER s ON s.OI_SUPPLIER_ID = i.OI_SUPPLIER_ID WHERE i.INVOICE_STATUS = 'Disputed' ORDER BY i.INVOICE_DATE DESC")
add("Which price book versions are loaded and for which contract and what is their escalation?",
    "SELECT s.SUPPLIER_NAME, p.PRICEBOOK_VERSION, p.CLM_CONTRACT_ID, MIN(p.EFFECTIVE_FROM) AS EFFECTIVE_FROM, MAX(p.EFFECTIVE_TO) AS EFFECTIVE_TO, MAX(p.ESCALATION_PCT) AS ESCALATION_PCT, COUNT(*) AS RATED_ITEMS, MIN(p.SOURCE_DOCUMENT) AS SOURCE_DOCUMENT FROM OI_PRICEBOOK_ITEM p JOIN OI_SUPPLIER s ON s.OI_SUPPLIER_ID = p.OI_SUPPLIER_ID GROUP BY s.SUPPLIER_NAME, p.PRICEBOOK_VERSION, p.CLM_CONTRACT_ID ORDER BY s.SUPPLIER_NAME, EFFECTIVE_FROM")
add_eval_only("What is the total price book variance by supplier and year and what share of rated lines was over contract?",
              "SELECT SUPPLIER_NAME, INVOICE_YEAR, COUNT(*) AS RATED_LINES, SUM(IS_OVER_CONTRACT) AS OVER_CONTRACT_LINES, ROUND(100.0 * SUM(IS_OVER_CONTRACT) / COUNT(*), 1) AS OVER_CONTRACT_PCT, ROUND(SUM(PRICE_VARIANCE_USD), 0) AS VARIANCE_USD FROM V_PRICEBOOK_VARIANCE GROUP BY SUPPLIER_NAME, INVOICE_YEAR ORDER BY SUPPLIER_NAME, INVOICE_YEAR")

# ---------------------------------------------------------------- CP3: OCTG descriptions
add("For 5-1/2 inch 20 lb/ft P-110 BTC production casing combined over 2025 to date list each supplier item description with its invoiced UOM and supplier count and line count and feet and price per foot.",
    f"SELECT SUPPLIER_ITEM_DESCRIPTION, INVOICED_UOM, COUNT(DISTINCT LIFNR) AS SUPPLIERS, COUNT(*) AS LINES, ROUND(SUM(STD_QUANTITY), 0) AS FEET, ROUND(SUM(LINE_AMOUNT_USD) / NULLIF(SUM(STD_QUANTITY), 0), 2) AS USD_PER_FT FROM V_INVOICE_LINE_CLASSIFIED WHERE GENERIC_PRODUCT_NAME = '{CASING}' AND INVOICE_YEAR >= 2025 GROUP BY SUPPLIER_ITEM_DESCRIPTION, INVOICED_UOM ORDER BY USD_PER_FT DESC")
add("For 5-1/2 inch 20 lb/ft P-110 BTC production casing only and 2025 to date combined rank suppliers by price per foot with line count and feet and spend.",
    f"SELECT SUPPLIER_NAME, COUNT(*) AS LINES, ROUND(SUM(STD_QUANTITY), 0) AS FEET, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD, ROUND(SUM(LINE_AMOUNT_USD) / NULLIF(SUM(STD_QUANTITY), 0), 2) AS USD_PER_FT FROM V_INVOICE_LINE_CLASSIFIED WHERE GENERIC_PRODUCT_NAME = '{CASING}' AND INVOICE_YEAR >= 2025 GROUP BY SUPPLIER_NAME ORDER BY USD_PER_FT")
add_eval_only("What is our OCTG spend by generic product and basin since 2025?",
              "SELECT GENERIC_PRODUCT_NAME, BASIN, ROUND(SUM(STD_QUANTITY), 0) AS FEET_OR_UNITS, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD, COUNT(DISTINCT LIFNR) AS SUPPLIERS FROM V_INVOICE_LINE_CLASSIFIED WHERE LEVEL1_FAMILY = 'OCTG & wellhead' AND INVOICE_YEAR >= 2025 GROUP BY GENERIC_PRODUCT_NAME, BASIN ORDER BY SPEND_USD DESC")

# ---------------------------------------------------------------- CP4: classification backlog
add("For 2026 group unclassified line spend by supplier name and supplier category and item description and review status with line count and amount sorted by amount.",
    "SELECT SUPPLIER_NAME, OI_SUPPLIER_CATEGORY, SUPPLIER_ITEM_DESCRIPTION, REVIEW_STATUS, COUNT(*) AS LINES, ROUND(SUM(LINE_AMOUNT_USD), 0) AS UNCLASSIFIED_USD FROM V_UNCLASSIFIED_SPEND WHERE INVOICE_YEAR = 2026 GROUP BY SUPPLIER_NAME, OI_SUPPLIER_CATEGORY, SUPPLIER_ITEM_DESCRIPTION, REVIEW_STATUS ORDER BY UNCLASSIFIED_USD DESC")
add("What share of line spend is classified to a generic product by year?",
    "SELECT INVOICE_YEAR, ROUND(SUM(LINE_AMOUNT_USD), 0) AS LINE_SPEND_USD, ROUND(SUM(CASE WHEN IS_CLASSIFIED = 1 THEN LINE_AMOUNT_USD ELSE 0 END), 0) AS CLASSIFIED_USD, ROUND(100.0 * SUM(CASE WHEN IS_CLASSIFIED = 1 THEN LINE_AMOUNT_USD ELSE 0 END) / SUM(LINE_AMOUNT_USD), 1) AS CLASSIFIED_PCT FROM V_INVOICE_LINE_CLASSIFIED GROUP BY INVOICE_YEAR ORDER BY INVOICE_YEAR")
add("Which items are waiting for steward review with an ML suggestion and what is the confidence?",
    "SELECT s.SUPPLIER_NAME, c.SUPPLIER_ITEM_CODE, c.SUPPLIER_ITEM_DESCRIPTION, c.INVOICED_UOM, c.CLASSIFICATION_METHOD, c.CONFIDENCE, c.CLASSIFIED_DATE, c.STEWARD_NOTE FROM SCM_ITEM_CLASSIFICATION c JOIN OI_SUPPLIER s ON s.OI_SUPPLIER_ID = c.OI_SUPPLIER_ID WHERE c.REVIEW_STATUS = 'Needs review' ORDER BY c.CONFIDENCE DESC")
add("Unclassified spend by supplier category in 2026 compared with that category's total line spend.",
    "SELECT OI_SUPPLIER_CATEGORY, ROUND(SUM(LINE_AMOUNT_USD), 0) AS LINE_SPEND_USD, ROUND(SUM(CASE WHEN IS_CLASSIFIED = 0 THEN LINE_AMOUNT_USD ELSE 0 END), 0) AS UNCLASSIFIED_USD, ROUND(100.0 * SUM(CASE WHEN IS_CLASSIFIED = 0 THEN LINE_AMOUNT_USD ELSE 0 END) / SUM(LINE_AMOUNT_USD), 1) AS UNCLASSIFIED_PCT FROM V_INVOICE_LINE_CLASSIFIED WHERE INVOICE_YEAR = 2026 GROUP BY OI_SUPPLIER_CATEGORY ORDER BY UNCLASSIFIED_USD DESC")
add_eval_only("Count supplier items by classification method and review status including the rows with no method and show the average confidence.",
              "SELECT CLASSIFICATION_METHOD, REVIEW_STATUS, COUNT(*) AS ITEMS, ROUND(AVG(CONFIDENCE), 2) AS AVG_CONFIDENCE FROM SCM_ITEM_CLASSIFICATION GROUP BY CLASSIFICATION_METHOD, REVIEW_STATUS ORDER BY ITEMS DESC")

# ---------------------------------------------------------------- CP5: operational hook
add("List V_AFE_PRODUCT_COST rows for completion-phase proppant and water logistics products whose first invoice date is in 2026 with AFE and well and basin and generic product and standard quantity and spend and average standard unit price.",
    "SELECT AFE_NUMBER, CORP_WELL_ID, BASIN, GENERIC_PRODUCT_NAME, STANDARD_UOM, ROUND(STD_QUANTITY, 0) AS STD_QUANTITY, ROUND(SPEND_USD, 0) AS SPEND_USD, ROUND(AVG_STD_UNIT_PRICE_USD, 2) AS AVG_STD_UNIT_PRICE_USD FROM V_AFE_PRODUCT_COST WHERE USE_PHASE = 'Completion' AND FIRST_INVOICE_DATE >= DATE '2026-01-01' AND LEVEL1_FAMILY IN ('Proppant', 'Water logistics') ORDER BY SPEND_USD DESC")
add("Proppant family spend per lateral foot by basin: sum V_AFE_PRODUCT_COST proppant spend with first invoice date since 2025 per well then divide by lateral length from OI_REF_WELL for wells with a lateral.",
    "SELECT a.BASIN, COUNT(DISTINCT a.CORP_WELL_ID) AS WELLS, ROUND(SUM(a.SPEND_USD), 0) AS PROPPANT_SPEND_USD, ROUND(SUM(w.LATERAL_LENGTH_FT), 0) AS LATERAL_FT, ROUND(SUM(a.SPEND_USD) / NULLIF(SUM(w.LATERAL_LENGTH_FT), 0), 2) AS USD_PER_LATERAL_FT FROM (SELECT CORP_WELL_ID, BASIN, SUM(SPEND_USD) AS SPEND_USD FROM V_AFE_PRODUCT_COST WHERE LEVEL1_FAMILY = 'Proppant' AND FIRST_INVOICE_DATE >= DATE '2025-01-01' GROUP BY CORP_WELL_ID, BASIN) a JOIN OI_REF_WELL w ON w.CORP_WELL_ID = a.CORP_WELL_ID WHERE w.LATERAL_LENGTH_FT > 0 GROUP BY a.BASIN ORDER BY USD_PER_LATERAL_FT DESC")
add("Top 25 wells by proppant family spend per lateral foot using V_AFE_PRODUCT_COST rows with first invoice date since 2025 and OI_REF_WELL lateral length with the number of proppant products per well.",
    "SELECT a.CORP_WELL_ID, w.WELL_NAME, w.BASIN, w.LATERAL_LENGTH_FT, ROUND(SUM(a.SPEND_USD), 0) AS PROPPANT_SPEND_USD, ROUND(SUM(a.SPEND_USD) / NULLIF(w.LATERAL_LENGTH_FT, 0), 2) AS USD_PER_LATERAL_FT, COUNT(DISTINCT a.GENERIC_PRODUCT_NAME) AS PROPPANT_PRODUCTS FROM V_AFE_PRODUCT_COST a JOIN OI_REF_WELL w ON w.CORP_WELL_ID = a.CORP_WELL_ID WHERE a.LEVEL1_FAMILY = 'Proppant' AND a.FIRST_INVOICE_DATE >= DATE '2025-01-01' AND w.LATERAL_LENGTH_FT > 0 GROUP BY a.CORP_WELL_ID, w.WELL_NAME, w.BASIN, w.LATERAL_LENGTH_FT ORDER BY USD_PER_LATERAL_FT DESC LIMIT 25")
add("Do the OpenInvoice invoices reconcile to what the ERP posted? Compare stamped invoice totals to the ERP amounts by month in 2026.",
    "SELECT DATE_TRUNC('MONTH', i.INVOICE_DATE) AS INVOICE_MONTH, COUNT(*) AS INVOICES, ROUND(SUM(i.INVOICE_TOTAL_USD), 0) AS OPENINVOICE_USD, ROUND(SUM(e.ERP_AMOUNT_USD), 0) AS ERP_POSTED_USD, ROUND(SUM(i.INVOICE_TOTAL_USD) - SUM(e.ERP_AMOUNT_USD), 2) AS DIFFERENCE_USD FROM OI_INVOICE i JOIN OI_ERP_INTEGRATION_LOG e ON e.ERP_INVOICE_ID = i.ERP_INVOICE_ID WHERE i.INVOICE_DATE >= DATE '2026-01-01' GROUP BY DATE_TRUNC('MONTH', i.INVOICE_DATE) ORDER BY INVOICE_MONTH")
add("Using V_AFE_PRODUCT_COST proppant family rows with first invoice date in 2026 show AFE count and proppant spend by basin and ten percent of that spend as the impact of a ten percent price rise.",
    "SELECT BASIN, COUNT(DISTINCT AFE_NUMBER) AS AFES, ROUND(SUM(SPEND_USD), 0) AS PROPPANT_SPEND_2026_USD, ROUND(SUM(SPEND_USD) * 0.10, 0) AS IMPACT_OF_10PCT_USD FROM V_AFE_PRODUCT_COST WHERE LEVEL1_FAMILY = 'Proppant' AND FIRST_INVOICE_DATE >= DATE '2026-01-01' AND BASIN IS NOT NULL GROUP BY BASIN ORDER BY IMPACT_OF_10PCT_USD DESC")
add_eval_only("Which suppliers invoiced us in OpenInvoice in 2026 and what does the SAP vendor master say their category and city are?",
              "SELECT s.SUPPLIER_NAME, s.LIFNR, v.VENDOR_CATEGORY AS SAP_VENDOR_CATEGORY, v.ORT01 AS SAP_CITY, s.OI_SUPPLIER_CATEGORY, ROUND(SUM(i.INVOICE_TOTAL_USD), 0) AS SPEND_2026_USD FROM OI_INVOICE i JOIN OI_SUPPLIER s ON s.OI_SUPPLIER_ID = i.OI_SUPPLIER_ID JOIN OI_REF_VENDOR v ON v.LIFNR = s.LIFNR WHERE i.INVOICE_DATE >= DATE '2026-01-01' GROUP BY s.SUPPLIER_NAME, s.LIFNR, v.VENDOR_CATEGORY, v.ORT01, s.OI_SUPPLIER_CATEGORY ORDER BY SPEND_2026_USD DESC")
add_eval_only("For completion AFEs dated in 2026 that have OpenInvoice capital lines show the gross AFE amount and the proppant and completion chemical and total OpenInvoice spend and that total as a percent of the AFE.",
              "SELECT r.AFE_NUMBER, r.CORP_WELL_ID, r.AFE_DATE, r.GROSS_AFE_AMOUNT, ROUND(SUM(CASE WHEN a.LEVEL1_FAMILY = 'Proppant' THEN a.SPEND_USD ELSE 0 END), 0) AS PROPPANT_USD, ROUND(SUM(CASE WHEN a.LEVEL1_FAMILY = 'Production & completion chemicals' THEN a.SPEND_USD ELSE 0 END), 0) AS COMPLETION_CHEMICALS_USD, ROUND(SUM(a.SPEND_USD), 0) AS OPENINVOICE_SPEND_USD, ROUND(100.0 * SUM(a.SPEND_USD) / NULLIF(r.GROSS_AFE_AMOUNT, 0), 1) AS SHARE_OF_AFE_PCT FROM OI_REF_AFE r JOIN V_AFE_PRODUCT_COST a ON a.AFE_NUMBER = r.AFE_NUMBER WHERE r.AFE_TYPE = 'Completion' AND r.AFE_DATE >= DATE '2026-01-01' GROUP BY r.AFE_NUMBER, r.CORP_WELL_ID, r.AFE_DATE, r.GROSS_AFE_AMOUNT ORDER BY OPENINVOICE_SPEND_USD DESC")

# ---------------------------------------------------------------- operations and AP
add("Average days from invoice date to approval date by supplier category for 2026 invoices that have an approval date.",
    "SELECT OI_SUPPLIER_CATEGORY, COUNT(*) AS INVOICES, ROUND(AVG(DATEDIFF('day', INVOICE_DATE, APPROVED_DATE)), 1) AS AVG_DAYS_TO_APPROVE FROM OI_INVOICE WHERE INVOICE_DATE >= DATE '2026-01-01' AND APPROVED_DATE IS NOT NULL GROUP BY OI_SUPPLIER_CATEGORY ORDER BY AVG_DAYS_TO_APPROVE DESC")
add("What share of each supplier's 2026 invoice value is fees and surcharges?",
    "SELECT s.SUPPLIER_NAME, COUNT(*) AS INVOICES, ROUND(SUM(i.INVOICE_TOTAL_USD), 0) AS INVOICE_USD, ROUND(SUM(i.SURCHARGES_USD), 0) AS SURCHARGES_USD, ROUND(100.0 * SUM(i.SURCHARGES_USD) / NULLIF(SUM(i.INVOICE_TOTAL_USD), 0), 2) AS SURCHARGE_PCT FROM OI_INVOICE i JOIN OI_SUPPLIER s ON s.OI_SUPPLIER_ID = i.OI_SUPPLIER_ID WHERE i.INVOICE_DATE >= DATE '2026-01-01' GROUP BY s.SUPPLIER_NAME HAVING SUM(i.SURCHARGES_USD) > 0 ORDER BY SURCHARGE_PCT DESC")
add_eval_only("Top 20 wells by produced water hauling spend in 2026 with pad and basin and barrels hauled and price per barrel.",
              "SELECT CORP_WELL_ID, PAD_ID, BASIN, ROUND(SUM(STD_QUANTITY), 0) AS BARRELS, ROUND(SUM(LINE_AMOUNT_USD), 0) AS SPEND_USD, ROUND(SUM(LINE_AMOUNT_USD) / NULLIF(SUM(STD_QUANTITY), 0), 3) AS USD_PER_BBL FROM V_INVOICE_LINE_CLASSIFIED WHERE GENERIC_PRODUCT_NAME = 'Produced water hauling, truck' AND INVOICE_YEAR = 2026 AND CORP_WELL_ID IS NOT NULL GROUP BY CORP_WELL_ID, PAD_ID, BASIN ORDER BY SPEND_USD DESC LIMIT 20")
add_eval_only("Compare the five water haulers on price per barrel hauled in 2026.",
              "SELECT SUPPLIER_NAME, ROUND(STD_QUANTITY, 0) AS BARRELS, ROUND(SPEND_USD, 0) AS SPEND_USD, ROUND(AVG_STD_UNIT_PRICE_USD, 3) AS USD_PER_BBL, ROUND(BEST_STD_UNIT_PRICE_USD, 3) AS BEST_USD_PER_BBL, ROUND(SAVINGS_AT_BEST_PRICE_USD, 0) AS SAVINGS_AT_BEST_PRICE_USD FROM V_SUPPLIER_ALTERNATIVES WHERE GENERIC_PRODUCT_NAME = 'Produced water hauling, truck' AND INVOICE_YEAR = 2026 ORDER BY USD_PER_BBL")
